-- TORVO V2 SALES ORDER REVISION + DEALER OK
-- Staging runtime verification required before production.
create or replace function revise_sales_order(p_sales_order uuid,p_lines jsonb,p_reason text) returns integer language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;d sales_documents%rowtype;ln jsonb;iid uuid;q numeric;r numeric;sub numeric:=0;rev integer;rg text;before_json jsonb;begin select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found or a.role not in('owner','admin','accountant') then raise exception 'Owner/Admin/Accountant required';end if;if nullif(trim(p_reason),'') is null or jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)=0 then raise exception 'Revision reason and lines required';end if;select * into d from sales_documents where id=p_sales_order and doc_type='sales_order' for update;if not found then raise exception 'Sales Order not found';end if;if exists(select 1 from sales_documents e where e.doc_type='estimate' and e.root_order_id=p_sales_order) then raise exception 'Estimate already exists; direct Sales Order revision is locked';end if;select rate_group into rg from dealers where id=d.dealer_id and status='approved';if rg is null then raise exception 'Approved Dealer rate group required';end if;select coalesce(jsonb_agg(jsonb_build_object('item_id',item_id,'qty',qty,'rate',rate,'amount',amount) order by id),'[]'::jsonb) into before_json from sales_document_lines where document_id=p_sales_order;delete from sales_document_lines where document_id=p_sales_order;for ln in select * from jsonb_array_elements(p_lines) loop begin iid:=(ln->>'item_id')::uuid;q:=(ln->>'qty')::numeric;exception when others then raise exception 'Invalid revision line';end;if q is null or q<=0 then raise exception 'Invalid quantity';end if;perform 1 from catalog_items where id=iid and active=true;if not found then raise exception 'Item unavailable';end if;select selling_rate into r from item_rates where item_id=iid and rate_group=rg and min_qty<=q order by min_qty desc limit 1;if r is null then raise exception 'Rate unavailable for revised quantity';end if;insert into sales_document_lines(document_id,item_id,qty,rate,amount)values(p_sales_order,iid,q,r,round(q*r,2));sub:=sub+round(q*r,2);end loop;rev:=coalesce(d.revision_no,1)+1;update sales_documents set subtotal=sub,final_payable=sub,revision_no=rev,status='revision_pending_dealer_ok' where id=p_sales_order;insert into sales_order_revisions(sales_order_id,revision_no,changed_by,actor_role,change_reason,before_data,after_data)values(p_sales_order,rev,a.id,a.role,upper(trim(p_reason)),jsonb_build_object('subtotal',d.subtotal,'status',d.status,'lines',before_json),jsonb_build_object('subtotal',sub,'status','revision_pending_dealer_ok','lines',p_lines));insert into audit_log(actor_id,action,entity_type,entity_id,details)values(a.id,'SALES_ORDER_REVISED','sales_order',p_sales_order::text,jsonb_build_object('revision_no',rev,'reason',upper(trim(p_reason)),'dealer_ok_invalidated',true));return rev;end;$$;
create or replace function send_sales_order_for_dealer_ok(p_sales_order uuid,p_note text default null) returns integer language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;d sales_documents%rowtype;begin select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found or a.role not in('owner','admin','accountant','salesman') then raise exception 'Authorized sales staff required';end if;select * into d from sales_documents where id=p_sales_order and doc_type='sales_order' for update;if not found then raise exception 'Sales Order not found';end if;if a.role='salesman' and not salesman_can_access_dealer(a.id,d.dealer_id) then raise exception 'Dealer is not assigned to this salesman';end if;if exists(select 1 from sales_documents e where e.doc_type='estimate' and e.root_order_id=p_sales_order) then raise exception 'Estimate already exists';end if;update sales_documents set status='awaiting_dealer_ok' where id=p_sales_order;insert into audit_log(actor_id,action,entity_type,entity_id,details)values(a.id,'SALES_ORDER_SENT_FOR_DEALER_OK','sales_order',p_sales_order::text,jsonb_build_object('revision_no',coalesce(d.revision_no,1),'note',nullif(trim(p_note),''),'delivery_channel','prepared_not_sent'));return coalesce(d.revision_no,1);end;$$;
create or replace function dealer_confirm_sales_order(p_sales_order uuid,p_revision integer) returns void language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;d sales_documents%rowtype;did uuid;begin select * into a from app_users where auth_user_id=auth.uid() and active=true and role='dealer';if not found then raise exception 'Dealer login required';end if;did:=a.dealer_id;if did is null then select dealer_id into did from app_user_dealer_links where user_id=a.id limit 1;end if;select * into d from sales_documents where id=p_sales_order and doc_type='sales_order' for update;if not found or d.dealer_id<>did then raise exception 'Sales Order not available';end if;if d.status<>'awaiting_dealer_ok' then raise exception 'Sales Order is not awaiting Dealer OK';end if;if coalesce(d.revision_no,1)<>p_revision then raise exception 'Revision changed; review latest Sales Order';end if;update sales_documents set status='dealer_ok' where id=p_sales_order;insert into audit_log(actor_id,action,entity_type,entity_id,details)values(a.id,'DEALER_CONFIRMED_SALES_ORDER','sales_order',p_sales_order::text,jsonb_build_object('revision_no',p_revision));end;$$;
revoke all on function revise_sales_order(uuid,jsonb,text),send_sales_order_for_dealer_ok(uuid,text),dealer_confirm_sales_order(uuid,integer) from public,anon;grant execute on function revise_sales_order(uuid,jsonb,text),send_sales_order_for_dealer_ok(uuid,text),dealer_confirm_sales_order(uuid,integer) to authenticated;
